 decorateSourcing();decoratePricing();decorateImports();decorateAttention();decorateOperations();
 const screen=settings?'settings:'+settingsTitle:'view:'+view;if(screen!==lastScreen){lastScreen=screen;window.scrollTo(0,0)}
 $$('[name=followups]').forEach(el=>{const label=el.closest('label');if(label)label.hidden=true});if(settings&&$('#mp-settings [name=followups]')&&!$('#native-followup-note')){const note=document.createElement('p');note.id='native-followup-note';note.className='mp-settings-note';note.textContent='Vector responds when a buyer sends a new message.';$('#mp-settings').append(note)};
 const activeJob=nativeState.jobs.find(j=>j.state==='running');if(activeJob){coreMode='negotiating';$('#mp-core-title').textContent=taskNames[activeJob.kind]||'Working';syncCoreMotion()}
 $('#mp-state').textContent='Your listings';$('#mp-provider').innerHTML='<span class="mp-dot"></span>'+esc(nativeState.provider);$('#mp-provider').setAttribute('aria-label','Connections');
 if(view==='Stock'&&!settings){const top=$('.inv-top');if(top)top.lastElementChild.textContent='Saved on this Mac';}
 const manual=$('#mp-manual-form');if(manual&&!$('#native-send')){const send=document.createElement('button');send.id='native-send';send.type='button';send.className='mp-small-button';send.textContent='Send reply';send.onclick=()=>{const r=rows.find(x=>x.id===selected),w=workFor(r),lead=w.leads.find(l=>l.id===leadSelection[r.id])||w.leads[0],message=manual.querySelector('textarea').value.trim();if(!message||!lead?.url){feedback('Sync this conversation first so the recipient is identified.');return}queueJob('manual',r,{leadURL:lead.url,message});feedback('Your reply is queued for this conversation.')};manual.append(send)}
