 if(view==='Buying'&&!settings){const r=rows.find(x=>x.id===selected);if(r&&!workFor(r).purchased&&$('#mp-detail')){const b=document.createElement('button');b.type='button';b.className='mp-small-button';b.textContent='Record purchase';b.onclick=()=>openPurchase(r);$('#mp-detail').append(b)}}
 if(view==='Buying'&&!settings&&$('#mp-work-toggle')){const button=$('#mp-work-toggle'),original=button.onclick,r=rows.find(x=>x.id===selected);button.onclick=()=>{original();if(r&&workFor(r).enabled&&!workFor(r).leads.length)queueJob('offer',r)}}
