 if(view==='Stock'&&!settings){$$('[data-stock-edit]').forEach(button=>{const r=rows.find(x=>x.id===+button.dataset.stockEdit);if(!r)return;button.onclick=()=>{openStockEdit(r);const form=$('#inv-edit');const description=document.createElement('label');description.className='inv-label';description.textContent='Description';const editor=document.createElement('textarea');editor.value=r.detail||'';editor.rows=4;description.append(editor);form.prepend(description);const save=form.onsubmit;form.onsubmit=async e=>{const detail=editor.value;await save(e);if(!settings){r.detail=detail;saveSoon()}};if(r.view!=='Sold'){const sold=document.createElement('button');sold.type='button';sold.className='mp-small-button';sold.textContent='Record sale';sold.onclick=()=>openSale(r);form.append(sold)}}})}
