 if(enabled){stopSearch();laneEnabled.Buying=false;addActivity('Buying automation turned off');render();feedback('Buying automation is off. Sourcing and purchase negotiations are paused.');saveSoon();return}
 if(nativeState.scanning)stopSearch();
