function renderAnalytics(){const sales=nativeState.sales,received=sales.reduce((a,s)=>a+s.revenue,0),cost=sales.reduce((a,s)=>a+s.cost,0),inventory=stockRows(),unknown=inventory.filter(r=>r.costKnown===false).length,held=inventory.filter(r=>r.costKnown!==false).reduce((a,r)=>a+r.qty*r.offer,0),metrics=nativeState.metrics||{},lastCheck=metrics.lastInboxPoll?new Date(metrics.lastInboxPoll).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'Not checked';$('#mp-business').innerHTML='<div class="mp-money-grid"><div class="mp-money-stat"><span>Sales received</span><strong>'+money(received)+'</strong></div><div class="mp-money-stat"><span>Realized profit</span><strong>'+(sales.some(s=>s.costKnown===false)?'Cost missing':money(received-cost))+'</strong></div><div class="mp-money-stat"><span>Inventory cost</span><strong>'+(unknown?'Incomplete':money(held))+'</strong>'+(unknown?'<small>'+money(held)+' recorded · '+unknown+' items need cost</small>':'')+'</div></div><section class="mp-chart-panel"><h3>Automation efficiency</h3><div class="mp-money-grid"><div class="mp-money-stat"><span>Inbox checks</span><strong>'+(metrics.inboxPolls||0)+'</strong></div><div class="mp-money-stat"><span>Checks with changes</span><strong>'+(metrics.pollsWithChanges||0)+'</strong></div><div class="mp-money-stat"><span>AI requests</span><strong>'+(metrics.aiCalls||0)+'</strong></div><div class="mp-money-stat"><span>Sourcing checks</span><strong>'+(metrics.sourceFeedChecks||0)+'</strong></div><div class="mp-money-stat"><span>AI sourcing reviews</span><strong>'+(metrics.sourceAIRuns||0)+'</strong></div><div class="mp-money-stat"><span>Last inbox check</span><strong>'+esc(lastCheck)+'</strong></div></div></section><section class="mp-chart-panel"><h3>Recorded sales</h3><svg id="native-sales-chart" role="img" aria-label="Revenue and profit from recorded sales"></svg><p class="mp-chart-readout">'+sales.length+' sales recorded · CAD · Cyan: revenue · Violet: profit · Coral: loss</p></section><div class="inv-scroll"><table class="inv-table"><thead><tr><th>Item</th><th>Date</th><th>Revenue</th><th>Profit</th></tr></thead><tbody>'+sales.slice().reverse().map(s=>'<tr><td>'+esc(s.name)+'</td><td>'+new Date(s.date).toLocaleDateString()+'</td><td>'+money(s.revenue)+'</td><td>'+(s.costKnown===false?'Unknown':money(s.revenue-s.cost))+'</td></tr>').join('')+'</tbody></table></div>';const el=$('#native-sales-chart'),width=Math.max(280,el.parentElement.clientWidth-36),height=220,values=sales.slice(-20);el.setAttribute('viewBox','0 0 '+width+' '+height);el.style.width='100%';el.style.height='220px';if(!values.length){el.innerHTML='<text x="20" y="100" fill="#a0b3c2" font-size="14">Record your first sale from Inventory.</text>';return}const svg=d3.select(el),x=d3.scaleBand().domain(values.map(s=>s.id)).range([65,width-15]).padding(.25),y=d3.scaleLinear().domain([Math.min(0,...values.map(s=>s.revenue-s.cost)),Math.max(1,...values.map(s=>s.revenue))]).nice().range([180,15]);svg.append('g').attr('transform','translate(65,0)').call(d3.axisLeft(y).ticks(4));svg.append('text').attr('x',10).attr('y',12).attr('fill','#a0b3c2').text('CAD');svg.selectAll('rect').data(values).join('rect').attr('x',s=>x(s.id)).attr('y',s=>y(s.revenue)).attr('width',x.bandwidth()).attr('height',s=>y(0)-y(s.revenue)).attr('fill','#70e8ed').append('title').text(s=>s.name+': revenue '+money(s.revenue)+', profit '+(s.costKnown===false?'Unknown':money(s.revenue-s.cost)));svg.append('g').selectAll('rect').data(values.filter(s=>s.costKnown!==false)).join('rect').attr('x',s=>x(s.id)+x.bandwidth()*.3).attr('width',x.bandwidth()*.4).attr('y',s=>y(Math.max(0,s.revenue-s.cost))).attr('height',s=>Math.abs(y(s.revenue-s.cost)-y(0))).attr('fill',s=>s.revenue-s.cost<0?'#ff987e':'#a6a0ff').append('title').text(s=>'Profit '+(s.costKnown===false?'Unknown':money(s.revenue-s.cost)));svg.append('text').attr('x',width/2).attr('y',215).attr('fill','#a0b3c2').attr('text-anchor','middle').text('Sales, oldest to newest')}
