const originalOpenIntake=openIntake;
openIntake=function(){originalOpenIntake();const p=$('.inv-intake .mp-settings-note');if(p)p.textContent='Paste spreadsheet rows or dictate into the text box. AI can organize a rough list; review the extracted values before adding.';const b=document.createElement('button');b.type='button';b.className='mp-small-button';b.textContent='Organize with AI';$('#inv-preview').after(b);b.onclick=async()=>{const text=$('#inv-paste').value.trim();if(!text)return;b.disabled=true;try{const fields={specifications:{type:['string','null']},accessories:{type:['string','null']}};invFields.forEach(([k,l,t])=>fields[k]={type:t==='number'?['number','null']:['string','null']});const result=await infer('Extract inventory from this text. Preserve quantities and costs exactly; unknown values must be null. Never invent prices or condition. Text:\n'+text,objectSchema({items:{type:'array',items:objectSchema(fields)}}));intake=result.items.map(x=>({...x,name:x.name||'',sku:x.sku||'',qty:x.qty??1,offer:x.offer??0,costKnown:x.offer!=null,ask:x.ask??0,minimum:x.minimum??0,category:x.category||'',condition:x.condition||'',location:x.location||intakePolicy.location,photo:'',policy:intakePolicy.mode}));intakeError='';renderIntakeRows()}catch(e){intakeError=e.message;renderIntakeRows()}finally{b.disabled=false}}};
