function safeImageSource(value){if(typeof value!=='string')return '';if(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value))return value;try{const u=new URL(value);if(u.protocol==='https:'&&(/(^|\.)fbcdn\.net$/.test(u.hostname)||/(^|\.)fbsbx\.com$/.test(u.hostname)))return u.href}catch{}return ''}

function itemRevision(job){const r=rows.find(r=>r.id===job.itemId);return r?JSON.stringify([r.name,r.ask,r.minimum,r.condition,r.qty,r.detail,r.policy,r.specifications,r.accessories,r.pricingStrategy,r.costKnown,r.offer,r.profitTarget,r.liveURL,r.photo,workFor(r).floor,workFor(r).offerLimit,auto,sellingRules,nativeState.provider]):JSON.stringify([auto,radius,maxPrice,minProfit,intakePolicy.location,nativeState.provider])}
function jobAllowed(job){const r=rows.find(r=>r.id===job.itemId);if(job.kind==='manual')return true;if(job.kind==='poll'){const side=job.side||'Selling';return laneEnabled[side]&&rows.some(r=>r.view===side&&monitoringWanted(r))}if(job.kind==='sync'&&job.recurring&&!monitoringWanted(r))return false;if(job.kind==='scan')return nativeState.scanning&&laneEnabled.Buying;if(['offer','reply','sync'].includes(job.kind))return r&&!workFor(r).purchased&&!workFor(r).closed&&laneEnabled[r.view]&&(job.kind==='sync'||workFor(r).enabled);if(job.kind==='publish'||job.kind==='price')return laneEnabled.Selling;return true}

